"""A stand-in skill validator behaving as I1-I4 state (scratch, never committed).

``W2120_OMIT`` (comma separated) leaves one rule out, to show the matching cases bite:
  generated      reads no generated copy (today's one-place reading)
  installed      reads no installed twin
  vendored_refuses  a vendored skill's key is a refusal (code SKILL_FORBIDDEN_KEY), exit 1
  vendored_all   treats every skill as vendored (names, never refuses)
  claude_list    the .claude list is the kernel list (version and output allowed there)
  key:<name>     the key <name> is allowed everywhere (e.g. key:sandbox)
  first_file     one finding per key, naming only the first file that carries it
  nokey          no key check at all (today)
  nofields       findings carry no file or key
  required_claude  .claude copies are held to the required-fields rule (version) too
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path

from gov.check.skill_validator import validate_file
from gov.util.frontmatter import with_body

OMIT = set(filter(None, os.environ.get("W2120_OMIT", "").split(",")))
KERNEL = "template/governance/kernel/skills"
INSTALLED = "governance/kernel/skills"
GENERATED = (".rulesync/skills", "template/.rulesync/skills", ".claude/skills")
KERNEL_LIST = {"name", "version", "description", "output", "metadata"}
CLAUDE_LIST = {"name", "description", "metadata"}


def skill_files(place: Path) -> list[Path]:
    return sorted(place.rglob("SKILL.md")) if place.is_dir() else ([place] if place.is_file() else [])


def kind(path: Path) -> str:
    text = path.as_posix()
    if "/.claude/skills/" in "/" + text or text.startswith(".claude/skills/"):
        return "claude"
    return "other"


def vendored(path: Path) -> bool:
    if "vendored_all" in OMIT:
        return True
    parts = path.parts
    return "superpowers" in parts or any(p.startswith("openspec-") for p in parts)


def main(argv: list[str]) -> int:
    args = [a for a in argv if a != "--both-layouts"]
    places: list[str] = []
    for arg in args:
        if not arg.startswith("template/"):
            places.append(arg)
            continue
        held = [p for p in (arg, arg[len("template/"):]) if Path(p).parent.is_dir()]
        if "installed" in OMIT:
            held = [p for p in held if p == arg]
        places.extend(held)
    if not places:
        print(json.dumps({"unmeasured": True, "reason": "no path"}))
        return 1
    files: list[Path] = []
    for place in places:
        files += skill_files(Path(place))
        if place.startswith(KERNEL) and "generated" not in OMIT:
            rel = place[len(KERNEL):].lstrip("/")
            for folder in GENERATED:
                files += skill_files(Path(folder) / rel if rel else Path(folder))
    seen, findings, keyed = set(), [], set()
    for path in files:
        if path.resolve() in seen:
            continue
        seen.add(path.resolve())
        is_vendored, claude = vendored(path), kind(path) == "claude"
        text = path.read_text(encoding="utf-8")
        front, _ = with_body(text)
        if not is_vendored and (not claude or "required_claude" in OMIT):
            for f in validate_file(path) or []:
                findings.append({**f, "file": str(path), "key": None})
        if front is None or "nokey" in OMIT:
            continue
        allowed = CLAUDE_LIST if claude and "claude_list" not in OMIT else KERNEL_LIST
        for key in front:
            if key in allowed or f"key:{key}" in OMIT:
                continue
            if "first_file" in OMIT and key in keyed:
                continue
            keyed.add(key)
            code = "SKILL_VENDORED_KEY" if is_vendored and "vendored_refuses" not in OMIT else "SKILL_FORBIDDEN_KEY"
            findings.append({"code": code, "file": str(path), "key": key, "message": f"key {key} in {path}"})
    if "nofields" in OMIT:
        findings = [{"code": f["code"], "message": f["message"]} for f in findings]
    print(json.dumps({"findings": findings}))
    return 1 if any(f["code"] != "SKILL_VENDORED_KEY" for f in findings) else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
